from __future__ import annotations

import importlib
import json
import os
import stat
import subprocess
import sys
import tomllib
from pathlib import Path

import pytest


CLI_PATH = Path(__file__).resolve().parents[1] / "render_env.py"
HEADER_LINE = "# GENERATED by make env-render from config/env/manifest.d - do not edit."


def _toml_table(values: dict[str, str]) -> str:
    return "{ " + ", ".join(f"{key} = {json.dumps(value)}" for key, value in values.items()) + " }"


def _modules():
    """Import implementation modules lazily so this RED suite still collects."""
    manifest = importlib.import_module("env.manifest")
    render = importlib.import_module("env.render_env")
    return manifest, render


def _targets(
    *,
    sections: tuple[str, ...] = ("Database",),
    envs: tuple[str, ...] = ("local",),
    audience: str = "backend",
    path: str | None = None,
    example: str | None = None,
    version: int = 1,
) -> str:
    lines = [
        f"version = {version}",
        "",
        "[targets.t]",
        f"audience = {json.dumps(audience)}",
        f"envs = {json.dumps(list(envs))}",
    ]
    if path is not None:
        lines.append(f"path = {json.dumps(path)}")
    if example is not None:
        lines.append(f"example = {json.dumps(example)}")
    lines.append(f"sections = {json.dumps(list(sections))}")
    return "\n".join(lines)


def _var(
    name: str,
    *,
    cls: str = "config",
    section: str = "Database",
    example: str = "example-value",
    values: dict[str, str] | None = None,
    secret: dict[str, str] | None = None,
    derive: str | None = None,
    doc: str | None = None,
    required: bool = True,
) -> str:
    lines = [
        "[[var]]",
        f"name = {json.dumps(name)}",
        f"class = {json.dumps(cls)}",
        'targets = ["t"]',
        f"section = {json.dumps(section)}",
    ]
    if doc is not None:
        lines.append(f"doc = {json.dumps(doc)}")
    lines.append(f"example = {json.dumps(example)}")
    if not required:
        lines.append("required = false")
    if values is not None:
        lines.append(f"values = {_toml_table(values)}")
    if secret is not None:
        lines.append(f"secret = {_toml_table(secret)}")
    if derive is not None:
        lines.append(f"derive = {json.dumps(derive)}")
    return "\n".join(lines)


def _cli_env(**updates: str | None) -> dict[str, str]:
    child_env = os.environ.copy()
    for key, value in updates.items():
        if value is None:
            child_env.pop(key, None)
        else:
            child_env[key] = value
    return child_env


def _run_cli(root: Path, repo_root: Path, *args: str, env: dict[str, str] | None = None):
    return subprocess.run(
        [
            sys.executable,
            str(CLI_PATH),
            *args,
            "--root",
            str(root),
            "--repo-root",
            str(repo_root),
        ],
        capture_output=True,
        text=True,
        env=env,
        check=False,
    )


def test_example_render_has_exact_bytes_and_layout(write_manifest, tmp_path: Path):
    manifest_module, render_module = _modules()
    fragment = "\n\n".join(
        (
            _var(
                "DATABASE_URL",
                section="Database",
                example="https://db.example.test/name with space",
                values={"local": "https://db.example.test/name with space"},
                doc="doc line",
            ),
            _var(
                "OPTIONAL_FEATURE",
                section="Security",
                example="placeholder",
                values={"local": "enabled"},
                required=False,
            ),
        )
    )
    root = write_manifest(
        _targets(sections=("Database", "Security")),
        **{"10-main": f"version = 1\n\n{fragment}"},
    )
    manifest = manifest_module.load_manifest(root)
    rendered = render_module.render_target(manifest, "t", None)
    digest = manifest_module.target_digest(manifest, "t")

    assert render_module.HEADER_LINE == HEADER_LINE
    assert rendered == (
        f"{HEADER_LINE}\n"
        f"# target: t env: example digest: {digest}\n"
        "\n"
        "# == Database ==\n"
        "# doc line\n"
        "DATABASE_URL='https://db.example.test/name with space'\n"
        "\n"
        "# == Security ==\n"
        "# OPTIONAL_FEATURE=placeholder\n"
    )


@pytest.mark.parametrize(
    ("value", "expected"),
    (
        ("has space", "'has space'"),
        ("has#hash", "'has#hash'"),
        ('with"quote', "'with\"quote'"),
        ("it's quoted", '"it\'s quoted"'),
        ("cash$value", "'cash$value'"),
        ("slash\\value", "'slash\\value'"),
        ("https://example.test/path?x=1", "https://example.test/path?x=1"),
        ('{"k":"v","x":"y"}', "'{\"k\":\"v\",\"x\":\"y\"}'"),
        ("", ""),
        ("tilde~home", "'tilde~home'"),
        ("define('A', true);", '"define(\'A\', true);"'),
    ),
    ids=(
        "space",
        "hash",
        "double-quote",
        "single-quote",
        "dollar",
        "backslash",
        "plain-url",
        "json",
        "empty",
        "tilde",
        "php-single-quotes",
    ),
)
def test_values_use_contract_quoting(write_manifest, value: str, expected: str):
    _, render_module = _modules()
    fragment = f"version = 1\n\n{_var('VALUE', example=value, values={'local': value})}"
    root = write_manifest(_targets(), **{"10-values": fragment})
    rendered = render_module.render_target(
        importlib.import_module("env.manifest").load_manifest(root), "t", None
    )

    assert f"VALUE={expected}" in rendered.splitlines()


@pytest.mark.parametrize(
    "value",
    (
        'it\'s "both"',
        "it's $cash",
        "it's back\\slash",
        "it's `tick`",
        "line\nbreak",
        "cr\rreturn",
    ),
    ids=("both-quotes", "dollar", "backslash", "backtick", "newline", "carriage-return"),
)
def test_unrepresentable_values_are_refused(write_manifest, value: str):
    _, render_module = _modules()
    runtime = "\n" in value or "\r" in value
    example = "plain-example" if runtime else value
    fragment = f"version = 1\n\n{_var('VALUE', example=example, values={'local': value})}"
    parsed = tomllib.loads(fragment)
    assert parsed["var"][0]["example"] == example
    assert parsed["var"][0]["values"]["local"] == value
    root = write_manifest(_targets(), **{"10-values": fragment})

    manifest = importlib.import_module("env.manifest").load_manifest(root)
    with pytest.raises(ValueError) as exc_info:
        render_module.render_target(manifest, "t", "local" if runtime else None)

    assert type(exc_info.value) is ValueError
    assert "VALUE" in str(exc_info.value)
    assert value not in str(exc_info.value)


def test_example_mode_uses_secret_example_without_resolving(write_manifest):
    _, render_module = _modules()
    root = write_manifest(
        _targets(),
        **{
            "10-secret": (
                "version = 1\n\n"
                + _var(
                    "SERVICE_PASSWORD",
                    cls="secret",
                    example="example-password",
                    secret={"local": "keychain:acx-local/SERVICE_PASSWORD"},
                )
            )
        },
    )

    def unexpected_resolve(name: str, ref: str) -> str:
        raise AssertionError(f"resolver called for {name} using {ref}")

    rendered = render_module.render_target(
        importlib.import_module("env.manifest").load_manifest(root),
        "t",
        None,
        resolve=unexpected_resolve,
    )

    assert "SERVICE_PASSWORD=example-password" in rendered.splitlines()


def test_runtime_uses_values_and_resolves_secret_ref(write_manifest):
    _, render_module = _modules()
    fragment = "\n\n".join(
        (
            _var("PUBLIC_URL", cls="public", values={"local": "https://public.example.test"}),
            _var("APP_MODE", values={"local": "development"}),
            _var(
                "SERVICE_PASSWORD",
                cls="secret",
                secret={"local": "env:ACX_SERVICE_PASSWORD"},
            ),
        )
    )
    root = write_manifest(_targets(), **{"10-runtime": f"version = 1\n\n{fragment}"})
    manifest = importlib.import_module("env.manifest").load_manifest(root)
    calls: list[tuple[str, str]] = []

    def resolve(name: str, ref: str) -> str:
        calls.append((name, ref))
        return "runtime-secret-value"

    rendered = render_module.render_target(manifest, "t", "local", resolve=resolve)

    assert rendered.splitlines()[1].startswith("# target: t env: local digest: ")
    assert "PUBLIC_URL=https://public.example.test" in rendered.splitlines()
    assert "APP_MODE=development" in rendered.splitlines()
    assert "SERVICE_PASSWORD=runtime-secret-value" in rendered.splitlines()
    assert calls == [("SERVICE_PASSWORD", "env:ACX_SERVICE_PASSWORD")]


