def test_derived_dsn_tracks_one_password_rotation(write_manifest):
    _, render_module = _modules()
    fragment = "\n\n".join(
        (
            _var("PGUSER", values={"local": "acx"}),
            _var("PGPASSWORD", cls="secret", secret={"local": "env:ACX_PGPASSWORD"}),
            _var("PGHOST", values={"local": "localhost:5432"}),
            _var(
                "POSTGRES_DSN",
                cls="secret",
                derive="postgresql://${PGUSER}:${PGPASSWORD}@${PGHOST}/service",
            ),
        )
    )
    root = write_manifest(_targets(), **{"10-database": f"version = 1\n\n{fragment}"})
    manifest = importlib.import_module("env.manifest").load_manifest(root)

    def render_with(password: str) -> str:
        return render_module.render_target(
            manifest,
            "t",
            "local",
            resolve=lambda name, ref: password,
        )

    before = render_with("pw1").splitlines()
    after = render_with("pw2").splitlines()
    changed_names = ("PGPASSWORD=", "POSTGRES_DSN=")
    assert "PGPASSWORD=pw1" in before
    assert "POSTGRES_DSN=postgresql://acx:pw1@localhost:5432/service" in before
    assert [line for line in before if not line.startswith(changed_names)] == [
        line for line in after if not line.startswith(changed_names)
    ]
    assert "PGPASSWORD=pw2" in after
    assert "POSTGRES_DSN=postgresql://acx:pw2@localhost:5432/service" in after


def test_render_is_deterministic_when_fragment_files_are_renamed(write_manifest):
    manifest_module, render_module = _modules()
    fragments = {
        "10-first": f"version = 1\n\n{_var('FIRST', values={'local': 'one'})}",
        "20-second": f"version = 1\n\n{_var('SECOND', values={'local': 'two'})}",
    }
    root = write_manifest(_targets(), **fragments)
    first_manifest = manifest_module.load_manifest(root)
    first_render = render_module.render_target(first_manifest, "t", None)
    first_digest = manifest_module.target_digest(first_manifest, "t")
    manifest_dir = root / "manifest.d"
    (manifest_dir / "10-first.toml").rename(manifest_dir / "15-renamed-first.toml")
    (manifest_dir / "20-second.toml").rename(manifest_dir / "25-renamed-second.toml")
    second_manifest = manifest_module.load_manifest(root)
    second_render = render_module.render_target(second_manifest, "t", None)

    assert second_render == first_render
    assert manifest_module.target_digest(second_manifest, "t") == first_digest
    assert second_render.splitlines()[1] == first_render.splitlines()[1]


def test_write_new_file_uses_mode_600_and_leaves_no_temp_file(write_manifest, tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "runtime.env"

    render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=value\n")

    assert stat.S_IMODE(path.stat().st_mode) == 0o600
    assert [entry.name for entry in tmp_path.iterdir()] == ["runtime.env"]


def test_overwriting_generated_file_keeps_mode_600(tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "runtime.env"
    render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=first\n")

    render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=second\n")

    assert stat.S_IMODE(path.stat().st_mode) == 0o600
    assert path.read_text(encoding="utf-8").endswith("KEY=second\n")


def test_failed_write_preserves_existing_file_and_cleans_up_temp_file(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
):
    _, render_module = _modules()
    path = tmp_path / "runtime.env"
    render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=first\n")

    def boom(*args, **kwargs):
        raise OSError("replace failed")

    monkeypatch.setattr(render_module.os, "replace", boom)

    with pytest.raises(OSError, match="replace failed"):
        render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=second\n")

    assert path.read_text(encoding="utf-8").endswith("KEY=first\n")
    assert stat.S_IMODE(path.stat().st_mode) == 0o600
    assert [entry.name for entry in tmp_path.iterdir()] == ["runtime.env"]


@pytest.mark.parametrize("kind", ("live symlink", "broken symlink", "directory"))
def test_writer_refuses_symlinks_and_directories_with_path(kind: str, tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "blocked.env"
    if kind == "live symlink":
        destination = tmp_path / "destination.env"
        destination.write_text("untouched\n", encoding="utf-8")
        path.symlink_to(destination)
    elif kind == "broken symlink":
        path.symlink_to(tmp_path / "missing-destination.env")
    else:
        path.mkdir()

    with pytest.raises(ValueError) as exc_info:
        render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nKEY=value\n")

    assert type(exc_info.value) is ValueError
    assert str(path) in str(exc_info.value)
    if kind == "live symlink":
        assert destination.read_text(encoding="utf-8") == "untouched\n"
        assert path.is_symlink()


