    path.write_text("APP_MODE=old\n", encoding="utf-8")

    with pytest.raises(ValueError) as exc_info:
        render_module.write_env_file(path, f"{render_module.HEADER_LINE}\nAPP_MODE=new\n")

    assert type(exc_info.value) is ValueError
