def test_adopt_backs_up_old_bytes_with_mode_600(tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "adopt.env"
    old_bytes = b"APP_MODE=old-placeholder\n"
    path.write_bytes(old_bytes)

    render_module.write_env_file(
        path,
        f"{render_module.HEADER_LINE}\nAPP_MODE=new-placeholder\n",
        adopt=True,
    )

    backup = tmp_path / "adopt.env.pre-envman"
    assert backup.read_bytes() == old_bytes
    assert stat.S_IMODE(backup.stat().st_mode) == 0o600


def test_adopt_refuses_unmanaged_key_without_revealing_its_value(tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "adopt.env"
    path.write_text("LEGACY_X=legacy-placeholder\n", encoding="utf-8")

    with pytest.raises(ValueError) as exc_info:
        render_module.write_env_file(
            path,
            f"{render_module.HEADER_LINE}\nCURRENT=present\n",
            adopt=True,
        )

    assert type(exc_info.value) is ValueError
    message = str(exc_info.value)
    assert "LEGACY_X" in message
    assert "legacy-placeholder" not in message


def test_adopt_allows_explicit_unmanaged_key(tmp_path: Path):
    _, render_module = _modules()
    path = tmp_path / "adopt.env"
    path.write_text("LEGACY_X=legacy-placeholder\n", encoding="utf-8")
    new_text = f"{render_module.HEADER_LINE}\nCURRENT=present\n"

    render_module.write_env_file(
        path,
        new_text,
        adopt=True,
        allow_unmanaged=frozenset({"LEGACY_X"}),
    )

    assert path.read_text(encoding="utf-8") == new_text


def test_check_example_returns_empty_for_matching_file(write_manifest, tmp_path: Path):
    _, render_module = _modules()
    root = write_manifest(
        _targets(example="app/.env.example"),
        **{
            "10-check": f"version = 1\n\n"
            f"{_var('APP_MODE', example='dev', values={'local': 'dev'})}"
        },
    )
    repo_root = tmp_path / "repo"
    example_path = repo_root / "app/.env.example"
    example_path.parent.mkdir(parents=True)
    manifest = importlib.import_module("env.manifest").load_manifest(root)
    example_path.write_text(render_module.render_target(manifest, "t", None), encoding="utf-8")

    assert render_module.check_example(manifest, "t", repo_root) == []


def test_check_example_reports_drift_with_target_or_path(write_manifest, tmp_path: Path):
    _, render_module = _modules()
    root = write_manifest(
        _targets(example="app/.env.example"),
        **{
            "10-check": f"version = 1\n\n"
            f"{_var('APP_MODE', example='dev', values={'local': 'dev'})}"
        },
    )
    repo_root = tmp_path / "repo"
    example_path = repo_root / "app/.env.example"
    example_path.parent.mkdir(parents=True)
    manifest = importlib.import_module("env.manifest").load_manifest(root)
    rendered = render_module.render_target(manifest, "t", None)
    example_path.write_text(rendered, encoding="utf-8")
    drifted_bytes = example_path.read_bytes().replace(b"APP_MODE=dev", b"APP_MODE=dew")
    assert drifted_bytes != rendered.encode("utf-8")
    example_path.write_bytes(drifted_bytes)

    messages = render_module.check_example(manifest, "t", repo_root)

    assert messages
    assert any(str(example_path) in message or "app/.env.example" in message for message in messages)


def test_check_runtime_hides_both_secret_values_on_mismatch(write_manifest, tmp_path: Path):
    _, render_module = _modules()
    root = write_manifest(
        _targets(),
        **{
            "10-check": (
                "version = 1\n\n"
                + _var("SERVICE_PASSWORD", cls="secret", secret={"local": "env:ACX_SECRET"})
            )
        },
    )
    manifest = importlib.import_module("env.manifest").load_manifest(root)
    path = tmp_path / "runtime.env"
    old_secret = "s3cr3t-old"
    new_secret = "s3cr3t-new"
    old_text = render_module.render_target(
        manifest, "t", "local", resolve=lambda name, ref: old_secret
    )
    path.write_text(old_text, encoding="utf-8")
    path.chmod(0o600)

    messages = render_module.check_runtime(
        manifest,
        "t",
        "local",
        path,
        resolve=lambda name, ref: new_secret,
    )

    assert messages == ["SERVICE_PASSWORD: secret differs"]
    assert all(old_secret not in message and new_secret not in message for message in messages)


def test_cli_renders_and_checks_all_examples_then_detects_drift(write_manifest, tmp_path: Path):
    _modules()
    targets = """version = 1

[targets.t]
audience = "backend"
envs = ["local"]
example = "app/.env.example"
sections = ["Application"]

[targets.u]
audience = "backend"
envs = ["local"]
example = "other/.env.example"
sections = ["Other"]
"""
    fragment = """version = 1

[[var]]
name = "APP_MODE"
class = "config"
targets = ["t"]
section = "Application"
example = "dev"
values = { local = "dev" }

[[var]]
name = "OTHER_MODE"
class = "config"
targets = ["u"]
section = "Other"
example = "ready"
values = { local = "ready" }
"""
    root = write_manifest(
        targets,
        **{"10-cli": fragment},
    )
    repo_root = tmp_path / "repo"
    example_paths = (
        repo_root / "app/.env.example",
        repo_root / "other/.env.example",
    )
    for example_path in example_paths:
        example_path.parent.mkdir(parents=True)
    child_env = _cli_env(ACX_T_SECRET=None)

    rendered = _run_cli(root, repo_root, "render", "--all-examples", env=child_env)
    assert rendered.returncode == 0, rendered.stderr
    assert all(example_path.is_file() for example_path in example_paths)

    checked = _run_cli(root, repo_root, "check", "--all-examples", env=child_env)
    assert checked.returncode == 0, checked.stderr
    later_example_path = example_paths[1]
    original_bytes = later_example_path.read_bytes()
    drifted_bytes = original_bytes.replace(b"OTHER_MODE=ready", b"OTHER_MODE=readx")
    assert drifted_bytes != original_bytes
    later_example_path.write_bytes(drifted_bytes)
    drifted = _run_cli(root, repo_root, "check", "--all-examples", env=child_env)
    assert drifted.returncode == 1


